    w = len(grid[0]) if h else 0

    out = [row[:] for row in grid]

    # Find the main vertical axis as the column with the most 1s.
    # If tied, prefer the rightmost one.
    counts = [0] * w
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                counts[c] += 1

    axis = 0
    best = -1
    for c in range(w):
        if counts[c] >= best:
            best = counts[c]
            axis = c

    # Mirror all 1-cells strictly to the right of the axis onto the left as 2s.
    for r in range(h):
        for c in range(axis + 1, w):
            if grid[r][c] == 1:
                mc = 2 * axis - c
                if 0 <= mc < w and out[r][mc] == 0:
                    out[r][mc] = 2

    return out

